#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;
const int N = 5000;

vector<int> factorArr[N + 1];
vector<long long> primes;

long long comb(int m, int n) {
    long long res = 1;
    vector<int> fnm(primes.size(), 0);
    for (size_t i = 0; i < primes.size(); i++) fnm[i] = factorArr[n][i];
    for (size_t i = 0; i < factorArr[m].size(); i++) fnm[i] += factorArr[m][i];
    for (int w = 1; w <= m; w++) {
        long long r = 1;
        for (size_t i = 0; i < primes.size(); i++) {
            long long p = primes[i];
            for (int pw = fnm[i] - factorArr[w][i] - factorArr[n - w][i] -
                          factorArr[m - w][i];
                 pw > 0; pw >>= 1) {
                if (pw & 1) r = r * p % mod;
                p = p * p % mod;
            }
        }
        res += r;
    }
    return res % mod;
}

int main() {
    vector<int> abc(3, 0);
    cin >> abc[0] >> abc[1] >> abc[2];
    sort(abc.begin(), abc.end());
    vector<bool> sieve(N + 1, false);
    sieve[0] = true;
    sieve[1] = true;
    for (int p = 0; p <= N; p++) {
        if (!sieve[p]) {
            primes.push_back((long long)p);
            for (int q = p * p; q <= N; q += p) sieve[q] = true;
        }
    }
    for (int j = 0; j <= N; j++) factorArr[j].assign(primes.size(), 0);
    for (size_t i = 0; i < primes.size(); i++) {
        long long p = primes[i];
        for (long long pp = p; pp <= N; pp *= p) {
            for (long long j = pp; j <= N; j += pp) factorArr[j][i]++;
        }
    }
    vector<int> *a = &factorArr[0];
    for (int j = 0; j <= N; j++) {
        for (size_t i = 0; i < a->size(); i++) factorArr[j][i] += (*a)[i];
        a = &factorArr[j];
    }
    cout << comb(abc[0], abc[1]) * comb(abc[0], abc[2]) % mod *
                comb(abc[1], abc[2]) % mod
         << endl;
    return 0;
}
